toolArgs.file_text:
@implements IAsyncDisposable
@inject IJSRuntime JS

<div class="message-area">
    <div class="area-header">
        <h5># @ChannelName</h5>
        <p>@ChannelDescription</p>
    </div>
    <div class="message-list" @ref="_messageListRef">
        @if (HasMoreMessages)
        {
            <div class="load-more-sentinel">
                <button class="btn btn-sm btn-outline-secondary"
                        @onclick="OnLoadMore"
                        disabled="@_loading">
                    @(_loading ? "Loading..." : "Load older messages")
                </button>
            </div>
        }
        @foreach (var message in Messages)
        {
            <MessageBubble Message="message"
                           ReplyCount="GetReplyCount(message.Id)"
                           OnOpenThread="OnOpenThread"
                           OnReact="OnReact" />
        }
    </div>
    <MessageInput Placeholder="@($"Message #{ChannelName}")" OnSubmit="HandleSend" />
</div>

@code {
    [Parameter, EditorRequired] public string ChannelName { get; set; } = string.Empty;
    [Parameter] public string ChannelDescription { get; set; } = string.Empty;
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    [Parameter] public bool HasMoreMessages { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSend { get; set; }

    private ElementReference _messageListRef;
    private IJSObjectReference? _module;
    private bool _loading;
    private bool _shouldScrollToBottom;

    private int GetReplyCount(int messageId)
        => ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    protected override void OnParametersSet()
    {
        // Scroll to bottom when messages change (new message sent)
        _shouldScrollToBottom = true;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>("import",
                "./Components/Chat/MessageArea.razor.js");
        }

        if (_shouldScrollToBottom && _module is not null)
        {
            _shouldScrollToBottom = false;
            await _module.InvokeVoidAsync("scrollToBottom", _messageListRef);
        }
    }

    private async Task HandleSend(string content)
    {
        await OnSend.InvokeAsync(content);
        _shouldScrollToBottom = true;
    }

    public async ValueTask DisposeAsync()
    {
        if (_module is not null)
        {
            await _module.DisposeAsync();
        }
    }
}

