arguments.file_text:
@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <ChannelSidebar Channels="_channels"
                    SelectedChannelId="_selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <div class="main-panel">
        @if (_currentChannel is not null)
        {
            <MessageArea ChannelName="@_currentChannel.Name"
                         ChannelDescription="@_currentChannel.Description"
                         Messages="_messages"
                         ThreadReplyCounts="_threadReplyCounts"
                         HasMoreMessages="_hasMoreMessages"
                         OnLoadMore="LoadMoreMessages"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnSend="SendMessage" />
        }

        @if (_threadRootMessage is not null)
        {
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        }
    </div>
</div>

@code {
    private List<Channel> _channels = [];
    private int _selectedChannelId;
    private Channel? _currentChannel;
    private List<Message> _messages = [];
    private Dictionary<int, int> _threadReplyCounts = new();
    private bool _hasMoreMessages = true;
    private int _skip;
    private const int PageSize = 50;

    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannelId = channelId;
        _currentChannel = _channels.First(c => c.Id == channelId);
        _skip = 0;
        _hasMoreMessages = true;
        _messages = [];
        _threadRootMessage = null;
        _threadReplies = [];
        _threadReplyCounts = new();

        await LoadMessages();
        await ChatService.MarkChannelReadAsync(channelId);

        // Clear unread count locally
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _currentChannel with { UnreadCount = 0 };
            _currentChannel = _channels[idx];
        }
    }

    private async Task LoadMessages()
    {
        var batch = await ChatService.GetMessagesAsync(_selectedChannelId, _skip, PageSize);
        if (batch.Count < PageSize)
        {
            _hasMoreMessages = false;
        }

        foreach (var msg in batch)
        {
            if (msg.ReplyToId is int rootId)
            {
                _threadReplyCounts.TryGetValue(rootId, out var count);
                _threadReplyCounts[rootId] = count + 1;
            }
        }

        // Show only top-level messages in the main channel view
        var topLevel = batch.Where(m => m.ReplyToId is null).ToList();
        _messages.InsertRange(0, topLevel);
        _skip += batch.Count;
    }

    private async Task LoadMoreMessages() => await LoadMessages();

    private async Task SendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(_selectedChannelId, content, null);
        _messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is null) return;

        _threadReplies = await ChatService.GetThreadAsync(messageId);
        _threadReplyCounts[messageId] = _threadReplies.Count;
    }

    private void CloseThread()
    {
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(
            _selectedChannelId, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);
        _threadReplyCounts[_threadRootMessage.Id] = _threadReplies.Count;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Update the reaction locally for immediate feedback
        var msg = _messages.FirstOrDefault(m => m.Id == args.MessageId);
        if (msg is null) return;

        var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
        if (existing is not null)
        {
            existing.Users.Add("You");
        }
        else
        {
            msg.Reactions.Add(new Reaction(args.Emoji, ["You"]));
        }
    }
}

.chat-container {
    display: flex;
    height: 100vh;
    width: 100vw;
    overflow: hidden;
}

.main-panel {
    flex: 1;
    display: flex;
    min-width: 0;
}

@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <ChannelSidebar Channels="_channels"
